    g = [row[:] for row in grid]

    # The colored object defines the pattern to find in the zero cells.
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not cells:
        return g
    r0 = min(r for r, c in cells)
    c0 = min(c for r, c in cells)
    pattern = [(r - r0, c - c0) for r, c in cells]

    # Label 4-connected components of zero cells.
    component = {}
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in component:
                continue
            idx = len(components)
            stack = [(r, c)]
            component[(r, c)] = idx
            comp_cells = []
            while stack:
                x, y = stack.pop()
                comp_cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0
                            and (nx, ny) not in component):
                        component[(nx, ny)] = idx
                        stack.append((nx, ny))
            components.append(comp_cells)

    matched = set()
    max_dr = max(dr for dr, dc in pattern)
    max_dc = max(dc for dr, dc in pattern)
    for r in range(h - max_dr):
        for c in range(w - max_dc):
            positions = [(r + dr, c + dc) for dr, dc in pattern]
            if all(grid[x][y] == 0 for x, y in positions):
                matched.add(component[positions[0]])

    for idx in matched:
        for r, c in components[idx]:
            g[r][c] = 1
    return g
