def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]

    # Use the non-background object as a template.
    colors = {}
    for row in grid:
        for value in row:
            if value != 0:
                colors[value] = colors.get(value, 0) + 1
    color = min(colors, key=colors.get)

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r - r0, c - c0) for r, c in points]
    max_r = max(r for r, c in shape)
    max_c = max(c for r, c in shape)

    # Find every placement of that shape on background cells.
    for r in range(h - max_r):
        for c in range(w - max_c):
            positions = [(r + dr, c + dc) for dr, dc in shape]
            if all(grid[x][y] == 0 for x, y in positions):
                for x, y in positions:
                    g[x][y] = color
    return g
